mapper.select:
SELECT 
FROM exam_attempt
WHERE user_id = #{userId}
  AND status = 1
  AND deadline IS NOT NULL
  AND deadline <= #{now}

SELECT COUNT(*)
FROM exam_attempt
WHERE user_id = #{userId}
  AND exam_id = #{examId}
  AND status IN (1, 2, 3)

SELECT COALESCE(MAX(attempt_no), 0)
FROM exam_attempt
WHERE user_id = #{userId}
  AND exam_id = #{examId}

mapper.update:
UPDATE exam_attempt
SET status             = #{status},
    user_score         = #{userScore},
    is_passed          = #{isPassed},
    submitted_at       = #{submittedAt},
    graded_at          = #{gradedAt},
    time_spent_seconds = #{timeSpentSeconds}
WHERE id = #{id}
  AND status = #{expectedStatus}

mapper.select:
SELECT e.id, e.title, e.description, e.duration_minutes, e.max_attempts, e.passing_score, e.start_time, e.end_time, p.title AS paper_title, p.total_score AS total_score, (SELECT COUNT(*) FROM exam_attempt a WHERE a.exam_id = e.id AND a.user_id = #{userId} AND a.status IN (1, 2, 3)) AS attempts_used, (SELECT a.id FROM exam_attempt a WHERE a.exam_id = e.id AND a.user_id = #{userId} AND a.status = 1 ORDER BY a.id DESC LIMIT 1) AS in_progress_attempt_id FROM exam e JOIN paper p ON p.id = e.paper_id WHERE e.status = 1 AND (e.start_time IS NULL OR e.start_time <= #{now}) AND (e.end_time IS NULL OR e.end_time >= #{now})
AND (e.title LIKE CONCAT('%', #{q.keyword}, '%') OR e.description LIKE CONCAT('%', #{q.keyword}, '%') OR p.title LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY (e.end_time IS NULL), e.end_time ASC, e.id DESC LIMIT #{q.offset}, #{q.pageSize}

SELECT COUNT(*)
FROM exam_attempt
WHERE user_id = #{userId}
